merge into T_CX_EMBRYO_MONTH_PLAN_SURPLUS a USING (
select #{ITEM.monthPlanApsVersion,jdbcType=VARCHAR} MONTH_PLAN_APS_VERSION, #{ITEM.monthPlanVersion,jdbcType=VARCHAR} MONTH_PLAN_VERSION, #{ITEM.year,jdbcType=VARCHAR} year, #{ITEM.month,jdbcType=VARCHAR} month, #{ITEM.materialCode,jdbcType=VARCHAR} material_code, #{ITEM.monthPlanQty,jdbcType=DOUBLE} month_plan_qty, #{ITEM.monthPlanModifyQty,jdbcType=DOUBLE} month_plan_modify_qty, #{ITEM.lastMonthStock,jdbcType=DOUBLE} last_month_stock, #{ITEM.embryoBadQty,jdbcType=DOUBLE} embryo_bad_qty, #{ITEM.monthFinishQty,jdbcType=DOUBLE} month_finish_qty, #{ITEM.monthRemainQty,jdbcType=DOUBLE} month_remain_qty, #{ITEM.dataSource,jdbcType=DECIMAL} data_source, #{ITEM.createBy,jdbcType=VARCHAR} create_by, #{ITEM.createTime,jdbcType=DATE} create_time, #{ITEM.updateBy,jdbcType=VARCHAR} update_by, #{ITEM.updateTime,jdbcType=DATE} update_time, #{ITEM.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.year = b.year and b.month = a.month and b.material_code = a.material_code AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.last_month_stock = NVL(b.last_month_stock, 0), a.month_finish_qty = NVL(b.month_finish_qty, 0), a.embryo_bad_qty = NVL(b.embryo_bad_qty, 0), a.month_remain_qty = NVL(b.month_remain_qty, 0), a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.MONTH_PLAN_APS_VERSION, a.MONTH_PLAN_VERSION, a.year, a.month, a.material_code, a.month_plan_qty, a.month_plan_modify_qty, a.last_month_stock, a.embryo_bad_qty, a.month_finish_qty, a.month_remain_qty, a.data_source, a.create_by, a.create_time, a.remark, a.del_flag) values (CX_EMBRYO_SURPLUS_SEQ.NEXTVAL, b.MONTH_PLAN_APS_VERSION, b.MONTH_PLAN_VERSION, b.year, b.month, b.material_code, b.month_plan_qty, b.month_plan_modify_qty, b.last_month_stock, b.embryo_bad_qty, b.month_finish_qty, b.month_remain_qty, 0, b.create_by, sysdate, b.remark, '0')
